#include <climits>
#include <functional>
#include <iostream>
#include <queue>
#include <utility>
#include <vector>

using Item = std::pair<int, int>;                             // (key, node)
using Graph = std::vector<std::vector<std::pair<int, int>>>;  // (neighbor, weight)

struct Tree {
    std::vector<int> parent;  // the node each one hangs from, -1 for node 0
    std::vector<int> edge;    // the weight of that edge
};

// Grows a tree from node 0. Prim keys a node by the one edge that would join it,
// Dijkstra by the length of the whole path from 0. Nothing else differs.
Tree grow(const Graph& adj, bool prim) {
    const int n = static_cast<int>(adj.size());
    std::vector<int> key(n, INT_MAX);
    std::vector<bool> done(n, false);
    Tree t{std::vector<int>(n, -1), std::vector<int>(n, 0)};
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    key[0] = 0;
    pq.push({0, 0});
    while (!pq.empty()) {
        const int u = pq.top().second;
        pq.pop();
        if (done[u]) {
            continue;  // stale entry
        }
        done[u] = true;
        for (const auto& [v, w] : adj[u]) {
            const int candidate = prim ? w : key[u] + w;
            if (!done[v] && candidate < key[v]) {
                key[v] = candidate;
                t.parent[v] = u;
                t.edge[v] = w;
                pq.push({candidate, v});
            }
        }
    }
    return t;
}

void report(const char* name, const Tree& t) {
    const int n = static_cast<int>(t.parent.size());
    std::cout << name << " edges";
    int weight = 0;
    for (int v = 1; v < n; ++v) {
        std::cout << ' ' << t.parent[v] << '-' << v;
        weight += t.edge[v];
    }
    int path = 0;
    for (int v = n - 1; v != 0; v = t.parent[v]) {
        path += t.edge[v];  // walk from the last node back to 0
    }
    std::cout << ", weight " << weight << ", path 0 to " << n - 1 << " costs " << path << '\n';
}

int main() {
    int n = 0;
    int m = 0;
    std::cin >> n >> m;
    Graph adj(n);
    for (int i = 0; i < m; ++i) {
        int u = 0;
        int v = 0;
        int w = 0;
        std::cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    report("Prim:    ", grow(adj, true));
    report("Dijkstra:", grow(adj, false));
    return 0;
}

