    const int rows = static_cast<int>(grid.size());
    const int cols = static_cast<int>(grid[0].size());
    auto h = [&](int cell) {
        return astar ? std::abs(goal / cols - cell / cols) + std::abs(goal % cols - cell % cols) : 0;
    };
    std::vector<int> dist(rows * cols, INT_MAX);
    std::vector<bool> done(rows * cols, false);
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    dist[start] = 0;
    pq.push({h(start), start});
    int expanded = 0;
    while (!pq.empty()) {
        const int u = pq.top().second;
        pq.pop();
        if (done[u]) {
            continue;
        }
        done[u] = true;
        ++expanded;
        if (u == goal) {
            break;
        }
        for (int d = 0; d < 4; ++d) {
            const int nr = u / cols + DR[d];
            const int nc = u % cols + DC[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] == '#') {
                continue;
            }
            const int v = nr * cols + nc;
            const int g = dist[u] + (grid[nr][nc] == '^' ? 3 : 1);
            if (g < dist[v]) {
                dist[v] = g;
                pq.push({g + h(v), v});
            }
        }
    }
    const int cost = dist[goal] == INT_MAX ? -1 : dist[goal];  // -1: no path
    std::cout << (astar ? "A*" : "Dijkstra") << ": cost " << cost << ", expanded " << expanded << '\n';
}

int main() {
    int rows = 0;
    int cols = 0;
    std::cin >> rows >> cols;
    std::vector<std::string> grid(rows);
    std::string cells;  // the rows joined, so cell r * cols + c is cells[r * cols + c]
    for (std::string& row : grid) {
        std::cin >> row;
        cells += row;
    }
    const int start = static_cast<int>(cells.find('S'));
    const int goal = static_cast<int>(cells.find('G'));
    search(grid, start, goal, false);
    search(grid, start, goal, true);
    return 0;
}

