const int DC[4] = {0, 0, -1, 1};

// A* that asks estimate(dr, dc) for a cell dr rows and dc columns from the goal.
// Mud (~) costs 5 to enter. Draws the path it finds with '*' and returns its cost.
template <typename Estimate>
int search(std::vector<std::string>& grid, int start, int goal, Estimate estimate, int& expanded) {
    const int rows = static_cast<int>(grid.size()), cols = static_cast<int>(grid[0].size());
    auto h = [&](int cell) { return estimate(std::abs(goal / cols - cell / cols), std::abs(goal % cols - cell % cols)); };
    std::vector<int> dist(rows * cols, INT_MAX);
    std::vector<int> parent(rows * cols, -1);
    std::vector<bool> done(rows * cols, false);
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    dist[start] = 0;
    pq.push({h(start), start});
    expanded = 0;
    while (!pq.empty() && !done[goal]) {
        const int u = pq.top().second;
        pq.pop();
        if (done[u]) {
            continue;
        }
        done[u] = true;
        ++expanded;
        for (int d = 0; d < 4; ++d) {
            const int nr = u / cols + DR[d], nc = u % cols + DC[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] == '#') {
                continue;
            }
            const int v = nr * cols + nc;
            const int g = dist[u] + (grid[nr][nc] == '~' ? 5 : 1);
            if (!done[v] && g < dist[v]) {  // a done cell is never reopened
                dist[v] = g;
                parent[v] = u;
                pq.push({g + h(v), v});
            }
        }
    }
    for (int v = parent[goal]; v != start; v = parent[v]) {
        grid[v / cols][v % cols] = '*';  // walk the path back from the goal
    }
    return dist[goal];
}

int main() {
    const std::vector<std::string> map = {
        "....................",
        "......~~~~~~........",
        "......~~~~~~...#....",
        ".S....~~~~~~...#.G..",
        "......~~~~~~...#....",
        "......~~~~~~........",
        "....................",
    };
    const int start = 3 * 20 + 1, goal = 3 * 20 + 17;  // row 3, columns 1 and 17
    for (int w : {0, 1, 2, 5}) {
        std::vector<std::string> grid = map;
        int expanded = 0;
        const int cost = search(grid, start, goal, [w](int dr, int dc) { return w * (dr + dc); }, expanded);
